	gr := g.newGraph()
	if err := gr.encoderLayers(g.detokL, x.Rows, from, to); err != nil {
		return nil, err
	}
	if _, err := gr.submit(); err != nil {
		return nil, err
	}
	return g.readX(x.Rows, g.enc.H), nil
