void main() {
    uint idx = gl_GlobalInvocationID.x;
    if (idx >= pc.tokens * pc.dim) {
        return;
    }
    float v = act[pc.inOff + idx];
    if (pc.wOff != NO_W) {
        v += wbuf[pc.wOff + (idx & (pc.dim - 1u))];
    }
#if COPY
    act[pc.outOff + idx] = v;
#else
    act[pc.outOff + idx] += v;
#endif
}
3:// x += conv + bias, in fp32, which closes one iteration of a generator
4:// residual block.
5://
6:// The bias is here and not after the first convolution of a pair because the
7:// first one's is immediately followed by an AdaIN, which subtracts the
8:// per-channel mean over time: adding a per-channel constant moves that mean by
9:// exactly the constant and leaves the variance alone, so it cancels
10:// identically. Only the bias of a convolution whose output reaches a residual
11:// add survives, which is every `conv2` and no `conv1`.
12://
13:// COPY replaces the accumulate with a plain store, which is what the
14:// generator's three parallel blocks need: each of them starts from the same
15:// input, so the stage's input is held once and copied into the running value
16:// before each one rather than uploaded three times.
17://
18://   pc.inOff   [T, C] fp32 convolution output
19://   pc.outOff  [T, C] fp32 running value, updated in place
20://   pc.wOff    [C] bias, or NO_W
21://   pc.dim     C, a power of two
void main() {
    uint idx = gl_GlobalInvocationID.x;
    if (idx >= pc.tokens * pc.dim) {
        return;
    }
    uint t = idx >> pc.aux2;
    uint c = idx & (pc.dim - 1u);
#if PAD
    uint src = t == 0u ? 1u : t - 1u;
#else
    uint src = t;
#endif
    float v = act[pc.inOff + (src << pc.aux2) + c];
    if (pc.wOff != NO_W) {
        v += wbuf[pc.wOff + c];
    }
    if (pc.aux0 != NO_W) {
        v += act[pc.aux0 + idx];
    }
    act[pc.outOff + idx] = v;
}

