func readI32(t *testing.T, path string) []int32 {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Skipf("no reference (%v); run reference/dump_ace_detok.py", err)
	}
	out := make([]int32, len(raw)/4)
