rep('''type encBlock struct {
	res     [3]resUnit
	s       snake
	down    conv // K = 2s·in
	stride  int
	in, out int
}''','''type encBlock struct {
	res     [3]resUnit
	s       snake
	down    conv // K = 2s·in (2s·2in split)
	stride  int
